import{_ as e,o as r,c as o,a2 as n}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"General","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/general.md","filePath":"es-ES/user-guide/settings/general.md","lastUpdated":1787287369000}'),i={name:"es-ES/user-guide/settings/general.md"};function s(t,a,l,d,c,u){return r(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h1><p>Seis pestañas: <strong>Sistema</strong>, <strong>Ventana de búsqueda rápida</strong>, <strong>Ventana de búsqueda completa</strong>, <strong>Vista previa</strong>, <strong>Navegación rápida</strong> y <strong>Vista previa y miniaturas</strong>.</p><h2 id="sistema" tabindex="-1">Sistema <a class="header-anchor" href="#sistema" aria-label="Permalink to &quot;Sistema&quot;">​</a></h2><ul><li><strong>Iniciar Lertaro con Windows</strong> — casilla, lanza Lertaro al iniciar sesión.</li><li><strong>Buscar actualizaciones automáticamente al iniciar</strong> — casilla.</li><li><strong>Actualización silenciosa automática al detectar una versión nueva</strong> — casilla, solo habilitada mientras la comprobación de arriba está activada; descarga e instala las actualizaciones en segundo plano sin preguntar.</li><li><strong>Habilitar aceleración por hardware</strong> — casilla, activada por defecto. Desactivarla obliga a la ventana de búsqueda rápida a renderizarse por software en lugar de usar Direct3D — esto evita que NVIDIA Advanced Optimus se niegue a cambiar de GPU en caliente mientras Lertaro está en ejecución (solo se ve afectada la ventana rápida, no toda la aplicación). Requiere reiniciar Lertaro para surtir efecto.</li><li><strong>Ocultar icono de la bandeja</strong> — casilla, desactivada por defecto. Se aplica de inmediato, sin necesidad de reiniciar. El mismo menú que muestra el clic derecho del icono de la bandeja siempre está disponible desde el <a href="./../hotkeys.html#icono-del-logotipo-en-el-cuadro-de-busqueda">propio logotipo de la ventana rápida</a> sin importar este ajuste, así que ocultar el icono de la bandeja nunca te deja sin forma de volver a Configuración o a Salir.</li><li><strong>Habilitar emulación Everything IPC</strong> — casilla, desactivada por defecto. Permite que herramientas de terceros dependientes de Everything (como Directory Opus, Total Commander y Flow Launcher) utilicen de forma transparente el índice en memoria de Lertaro para búsquedas y cálculo de tamaño de carpetas.</li><li><strong>Activar coincidencia difusa</strong> — casilla, activada por defecto. Con ella activada, un término de búsqueda normal coincide con que sus caracteres aparezcan en orden en cualquier parte del nombre; al desactivarla, un término normal debe aparecer como subcadena contigua en su lugar (<code>abc</code> deja de coincidir con <code>a-b-c</code>) — ver <a href="./../search-syntax.html#coincidencia-difusa-predeterminada">Sintaxis de búsqueda</a> para lo que cambia y lo que no. Se aplica de inmediato, sin necesidad de reiniciar.</li><li><strong>Carácter de prefijo global de tokens</strong> — cuadro de texto (máximo 1 carácter, predeterminado <code>:</code>). Define el carácter de prefijo global para dividir expresiones de tokens al final del cuadro de búsqueda. Los prefijos de filtrado de rutas y filtros personalizados se pueden configurar de forma independiente en <strong>Configuración → Plugins → CoreExtensions</strong>.</li><li><strong>Nivel de registro</strong> — desplegable: Error / Warn / Info (predeterminado) / Debug. Controla el nivel de detalle en los registros de la App, el Servicio y el Hook (ver <a href="./service-status.html">Estado del Servicio</a>).</li><li><strong>Idioma de interfaz</strong> — desplegable, poblado a partir de cada proveedor de traducción instalado (idiomas integrados más cualquiera que añada un plugin).</li></ul><p>La selección de tema se trasladó a su propia sección <a href="./appearance.html">Apariencia</a> — ver esa página para el selector de tema y la opción de &quot;seguir el ajuste de claro/oscuro del sistema&quot;.</p><h2 id="ventana-de-busqueda-rapida" tabindex="-1">Ventana de búsqueda rápida <a class="header-anchor" href="#ventana-de-busqueda-rapida" aria-label="Permalink to &quot;Ventana de búsqueda rápida&quot;">​</a></h2><p>Cubre tanto la apariencia de la barra de búsqueda rápida como la forma en que se priorizan sus resultados de búsqueda.</p><p><strong>Diseño de la barra de búsqueda</strong> — personaliza el tamaño y la posición en pantalla de la barra de búsqueda rápida:</p><ul><li><strong>Ancho de la barra de búsqueda (px)</strong> — rango 300–1200 px, por defecto 570 px.</li><li><strong>Alto de la barra de búsqueda (px)</strong> — rango 45–120 px, por defecto 60 px. Este número también determina el tamaño del icono de la fila de resultado, el tamaño de fuente del nombre/ruta, y la altura de fila (<code>altura / 60</code>), así que una barra de búsqueda más alta escala con ella toda la lista de resultados, manteniendo siempre las mismas proporciones entre icono y texto.</li><li><strong>Mostrar reloj en el cuadro de búsqueda</strong> — casilla, desactivada por defecto. Mientras el cuadro de búsqueda está vacío, sustituye el habitual texto de marcador de posición &quot;Escribe para buscar...&quot; por la fecha actual, el día de la semana y la hora. Desaparece en cuanto empiezas a escribir, igual que el marcador de posición al que sustituye. Solo en la ventana rápida — la ventana en línea siempre mantiene su marcador de posición normal, incluso con esto activado.</li><li><strong>Reabrir como ventana completa al repetir el atajo</strong> — casilla, desactivada por defecto. Normalmente, pulsar de nuevo el atajo de mostrar/ocultar mientras la ventana rápida ya está abierta simplemente la oculta; activar esto hace que la segunda pulsación cambie a la ventana completa en su lugar (trasladando la consulta que ya tuvieras escrita), en lugar de cerrar nada.</li><li><strong>Bloquear posición</strong> — casilla, desactivada por defecto. Impide arrastrar la ventana rápida, para que una pulsación accidental no la desplace del sitio donde la dejaste. Hacer clic derecho en el logo sigue restableciendo su posición, y <strong>Restablecer ajustes de diseño</strong> más abajo también quita el bloqueo junto con todo lo demás.</li><li>Botón <strong>Restablecer ajustes de diseño</strong> — restaura los cinco ajustes de arriba a sus valores predeterminados.</li></ul><p>Hacer clic derecho en el <a href="./../hotkeys.html#icono-del-logotipo-en-el-cuadro-de-busqueda">logotipo de la ventana rápida</a> restablece solo su posición en pantalla (no el tamaño), volviendo a centrarla igual que se centra en el primer arranque.</p><p><strong>Prioridad de tipo de resultado</strong> — la misma lista con flechas arriba/abajo (o arrastrar para reordenar) usada para <a href="#navegacion-rapida">Navegación rápida</a> más abajo: mueve un tipo de resultado (Aplicaciones, Configuración, Filtros de archivos, los propios elementos buscables de cualquier plugin de terceros, o la entrada integrada &quot;Archivos&quot;) arriba o abajo para que siempre supere en prioridad a los tipos que queden por debajo en los resultados de la ventana rápida, sin importar cuál haya coincidido en realidad mejor con el texto de la consulta. Historial y Favoritos siempre aparecen primero y no forman parte de esta lista.</p><p>Cada tipo también puede tener su propio <strong>activador</strong> de un solo carácter (opcional, un cuadro de texto por fila): escribir ese carácter como lo primero de todo en la ventana rápida muestra solo los resultados de ese tipo, ocultando todo lo demás — ver <a href="./../search-syntax.html#activador-de-tipo-de-resultado">Sintaxis de búsqueda</a> para ver ejemplos. Escribir solo el activador sin nada detrás todavía muestra un aviso de &quot;sigue escribiendo para buscar solo en X&quot; en lugar de &quot;Sin resultados de búsqueda&quot;. Elige un carácter con el que nunca empezarías normalmente una búsqueda real, ya que queda reservado en cuanto se le asigna a un tipo — un carácter de puntuación (por ejemplo, <code>;</code>) funciona de forma más fiable que un simple espacio, ya que un espacio suelto sin nada escrito detrás se trata igual que un cuadro de búsqueda vacío y no mostrará ese aviso.</p><h2 id="ventana-de-busqueda-completa" tabindex="-1">Ventana de búsqueda completa <a class="header-anchor" href="#ventana-de-busqueda-completa" aria-label="Permalink to &quot;Ventana de búsqueda completa&quot;">​</a></h2><p>Define el tamaño predeterminado de la ventana de búsqueda completa/principal (la ventana más grande que obtienes desde la barra de tareas o el acceso directo del menú Inicio, en contraposición a la ventana emergente rápida — ver <a href="./../getting-started.html#las-tres-ventanas">Primeros pasos</a>):</p><ul><li><strong>Ancho de la ventana (px)</strong> — rango 640–2000 px, por defecto 854 px.</li><li><strong>Alto de la ventana (px)</strong> — rango 400–1400 px, por defecto 480 px. Los mínimos coinciden con el propio límite de redimensionado de la ventana, así que un valor configurado nunca es sobrescrito en silencio por la propia ventana.</li><li>Botón <strong>Restablecer ajustes de la ventana de búsqueda</strong>.</li><li><strong>Permitir solo una ventana de búsqueda completa</strong> — casilla, desactivada por defecto. Al estar desactivada, puedes abrir varias ventanas completas independientes. Al activarla, volver a abrir la ventana completa activa una ya existente en vez de crear otra; una consulta transferida desde <strong>Mostrar más</strong> de la ventana rápida sustituye la consulta de esa ventana.</li></ul><p>Arrastrar el borde de la ventana para redimensionarla manualmente se recuerda automáticamente — la próxima vez que abras la ventana (o abras una nueva), vuelve con el tamaño que dejaste la última vez, y los campos de esta página se actualizan a juego. Redimensionar mientras está maximizada no sobrescribe el tamaño recordado; solo lo hace redimensionar en el estado normal (no maximizado).</p><p>La lista de resultados de la ventana completa no antepone elementos recuperados de Favoritos ni del Historial. Esos resultados personalizados permanecen en las ventanas rápida y en línea; la ventana completa conserva el orden de relevancia normal de los proveedores de búsqueda activos.</p><p><strong>Orden de columnas de la cuadrícula de resultados</strong> — la misma lista de reordenación usada en otras partes de Configuración (ver <a href="./favorites.html">Favoritos</a>): mueve una columna de la cuadrícula de resultados (Nombre, Ruta, Fecha de modificación, o cualquier columna aportada por un plugin) a la izquierda o a la derecha. Solo afecta al diseño de resultados en cuadrícula/tabla — no hay columnas que reordenar en el diseño de lista compacta.</p><p><strong>Orden de filtros de la barra lateral</strong> — el mismo mecanismo, para el orden en que aparecen los grupos de filtro de la barra lateral (Tipo, Fecha de modificación, y cualquier grupo añadido por un plugin).</p><p>Mientras se ejecuta una búsqueda completa, cada filtro de la barra lateral muestra en tiempo real cuántos resultados coinciden con la consulta actual. El recuento se actualiza a medida que llegan resultados y se reinicia al cambiar la consulta; no depende del filtro de la barra lateral seleccionado. El ancho de la barra lateral se ajusta al nombre y recuento más largos para que los nombres se muestren completos sin saltos de línea.</p><p><strong>Orden de secciones del menú de acciones</strong> — el mismo mecanismo, para el orden en que aparecen las secciones del <a href="./../actions-and-preview.html#menu-de-acciones">menú de acciones</a>: el grupo de acciones integradas, más una sección por cada plugin que contribuya acciones ahí (por ejemplo, Acciones personalizadas, o el menú contextual del shell de Windows). Una sección que aún no esté en esta lista recurre a su posición natural (primero las integradas, luego las secciones de plugin en el orden en que se aportaron).</p><p>Hacer clic en la cabecera de una columna de la cuadrícula de resultados recorre tres estados: ascendente, descendente, y un tercer clic la restablece de vuelta al orden predeterminado por relevancia (la flecha de orden de la cabecera desaparece). Esto se recuerda solo mientras Lertaro sigue en ejecución — salir de la aplicación (no solo cerrar la ventana) restablece el orden al predeterminado la próxima vez que la abras, a diferencia del orden de columnas/barra lateral de arriba, que se guarda de forma permanente.</p><h2 id="vista-previa" tabindex="-1">Vista previa <a class="header-anchor" href="#vista-previa" aria-label="Permalink to &quot;Vista previa&quot;">​</a></h2><ul><li><strong>Ancho de la vista previa (px)</strong> — rango 250–900 px.</li><li><strong>Alto de la vista previa (px)</strong> — rango 250–1200 px, con un tamaño predeterminado pensado para que el panel no sea excesivamente alto en una pantalla típica.</li><li>Botón <strong>Restablecer ajustes de la ventana de vista previa</strong>.</li></ul><p>La ventana de vista previa ignora el número actual de resultados — es un tamaño fijo, no un tamaño que crece con el contenido. Ver <a href="./../actions-and-preview.html">Menú de acciones y vista previa</a> para saber cómo se posiciona el panel.</p><h2 id="navegacion-rapida" tabindex="-1">Navegación rápida <a class="header-anchor" href="#navegacion-rapida" aria-label="Permalink to &quot;Navegación rápida&quot;">​</a></h2><p>Define el orden en que aparecen las secciones de nivel raíz del menú de <a href="./../hotkeys.html#navegacion-rapida-raton">Navegación rápida</a> — una sección por cada proveedor que contribuye (por ejemplo, Favoritos/Historial/carpetas configuradas, la lista de carpetas favoritas de Total Commander, los Favoritos de Directory Opus, las propias entradas de navegación rápida de un plugin), cada una etiquetada con su propio encabezado.</p><p><strong>Orden de proveedores</strong> — la misma lista con flechas arriba/abajo (o arrastrar para reordenar) usada en otras partes de Configuración (ver <a href="./favorites.html">Favoritos</a>): mueve un proveedor arriba o abajo para cambiar dónde cae su sección respecto a las demás. Solo se listan aquí los proveedores cuyo componente de plugin esté actualmente habilitado — uno deshabilitado en <a href="./plugins.html">Plugins</a> nunca llega a ser candidato al menú, así que no hay nada que ordenar para él.</p><h2 id="vista-previa-y-miniaturas" tabindex="-1">Vista previa y miniaturas <a class="header-anchor" href="#vista-previa-y-miniaturas" aria-label="Permalink to &quot;Vista previa y miniaturas&quot;">​</a></h2><p>Dos listas de prioridad independientes, cada una decidiendo qué proveedor tiene la primera opción de rechazo para su propia tarea — normalmente decidido puramente por la prioridad propia, fija e integrada, de cada proveedor, sin forma de cambiar eso salvo deshabilitando un proveedor por completo.</p><p><strong>Orden de proveedores de vista previa de archivo</strong> — para los <a href="./../actions-and-preview.html#vista-previa-quicklook">proveedores de vista previa de archivo</a> (por ejemplo, el plugin <a href="./../actions-and-preview.html#vista-previa-externa-mediante-quicklook-opcional">QuickLook Bridge</a> establece su propia prioridad por encima de cualquier previsualizador integrado). La misma lista con flechas arriba/abajo (o arrastrar para reordenar) usada en otras partes de Configuración (ver <a href="./favorites.html">Favoritos</a>): mueve un proveedor hacia arriba para que siempre gane sobre los que quedan por debajo, sin importar su propia prioridad integrada. Solo se listan aquí los proveedores cuyo componente de plugin esté actualmente habilitado — uno deshabilitado en <a href="./plugins.html">Plugins</a> de todos modos nunca llegaría a previsualizar nada.</p><p><strong>Orden de proveedores de miniaturas</strong> — el mismo mecanismo, para los iconos/miniaturas mostrados junto a los resultados en la propia lista de búsqueda (a diferencia del panel de vista previa) — más relevante en cuanto más de un plugin implemente un proveedor de miniaturas personalizado, ya que hoy en día solo existe un proveedor integrado.</p>',32)])])}const v=e(i,[["render",s]]);export{m as __pageData,v as default};
